mapper.select:
SELECT id, activity_id, start_time, end_time, booking_deadline, price_cents,
       capacity, available, status, created_at, updated_at
FROM sessions WHERE id = #{id}

mapper.update:
UPDATE sessions
SET start_time = #{startTime}, end_time = #{endTime}, booking_deadline = #{bookingDeadline},
    price_cents = #{priceCents}, capacity = #{capacity}, available = #{available}, updated_at = #{updatedAt}
WHERE id = #{id}

mapper.select:
SELECT id, activity_id, start_time, end_time, booking_deadline, price_cents,
       capacity, available, status, created_at, updated_at
FROM sessions
WHERE activity_id = #{activityId}

    AND status = #{status}

ORDER BY start_time ASC
